pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 val1, uint256 val2, uint256 unlock1, uint256 unlock2) public {
        // Bound amounts to avoid immediate revert from overflowing the contract balance; keep domain wide
        val1 = bound(val1, 0, type(uint256).max / 2);
        val2 = bound(val2, 0, type(uint256).max / 2);
        // Use a fresh address to isolate the caller's balance tracking
        address actor = address(uint160(uint256(keccak256(abi.encode(val1, val2)))));
        vm.assume(actor != address(0) && actor != address(this) && actor != address(c));
        // Ensure actor has enough ether for both calls
        vm.deal(actor, val1 + val2);
        // Record total sent
        uint256 totalSent = 0;
        vm.prank(actor);
        c.Put{value: val1}(unlock1);
        totalSent += val1;
        vm.prank(actor);
        c.Put{value: val2}(unlock2);
        totalSent += val2;
        // The invariant: the balance in Acc for the actor must equal totalSent
        ( , uint256 balance) = c.Acc(actor);
        assertTrue(balance == totalSent);
    }
}

