pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 fuzzedValue) public {
        // Admissible domain: fuzzedValue is non-zero to ensure a change in balance occurs.
        // We also require that it does not overflow when added to an existing balance in the correct contract.
        // The buggy version lacks an overflow check and may wrap around.
        vm.assume(fuzzedValue > 0);

        // Using a fresh address to have a clean starting balance of 0.
        address caller = address(0x123456);
        vm.assume(caller != address(0));

        // Record the balance before the call.
        uint256 balanceBefore = c.Acc(caller).balance;

        // Provide the caller with enough ether.
        vm.deal(caller, fuzzedValue);

        // Perform the Put call as the caller, sending the fuzzedValue.
        vm.prank(caller);
        c.Put{value: fuzzedValue}(uint256(0));

        // Record the balance after the call.
        uint256 balanceAfter = c.Acc(caller).balance;

        // The general rule for the reference (overflow-safe) contract:
        // balanceAfter must equal balanceBefore + fuzzedValue.
        // The mutant, missing the overflow check, can have an overflow wrap,
        // causing balanceAfter to be less than the expected sum.
        assertTrue(balanceAfter == balanceBefore + fuzzedValue);
    }
}

