pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 _unlockTime, uint256 collectAmt) public {
        // warp to a known future time so _unlockTime can be below it
        uint256 refTime = block.timestamp + 1000;
        vm.warp(refTime);
        address actor = address(0x1234);
        vm.deal(actor, 10 ether);
        // actor deposits, setting unlockTime via Put
        vm.prank(actor);
        c.Put{value: 1 ether}(_unlockTime);
        // ensure we are past any required min, and collectAmt <= actor balance
        vm.assume(collectAmt <= 1 ether);
        // attempt Collect before recorded unlockTime; ref should revert if before, bug may succeed
        bool ok;
        vm.prank(actor);
        try c.Collect(collectAmt) { ok = true; } catch { ok = false; }
        // ref invariant: if current time < stored unlockTime, Collect MUST revert.
        // Since we warp to refTime, stored unlockTime = max(_unlockTime, refTime)
        // current time == refTime, so if _unlockTime > refTime, time < stored unlockTime => revert.
        // bug sets unlockTime = _unlockTime, so if _unlockTime <= refTime, time >= stored unlockTime => no revert (violates).
        assertTrue(
            (block.timestamp >= (c.Acc(actor).unlockTime)) || !ok,
            "Collect should revert when before unlockTime"
        );
    }
}

